from pathlib import Path
from html import escape
import json
import math
import pandas as pd
import numpy as np

DATA = Path('/app/benchmark/data.csv')
TASK = Path('/app/benchmark/task_input.json')
OUT = Path('/app/output/final_report.html')

df = pd.read_csv(DATA, parse_dates=['Sale_Date'])
with TASK.open() as f:
    spec = json.load(f)

# Derived columns
work = df.copy()
work['Profit_Check_USD'] = work['Resale_Price_USD'] - work['Retail_Price_USD']
work['Resale_Retail_Ratio'] = work['Resale_Price_USD'] / work['Retail_Price_USD']
work['Sold_Above_Retail'] = work['Resale_Price_USD'] > work['Retail_Price_USD']
work['Year'] = work['Sale_Date'].dt.year
work['Month'] = work['Sale_Date'].dt.month
work['YearMonth'] = work['Sale_Date'].dt.to_period('M').astype(str)
work['Calendar_Month'] = work['Sale_Date'].dt.month_name().str[:3]

# Data integrity
missing = int(work.isna().sum().sum())
profit_max_diff = float((work['Profit_Margin_USD'] - work['Profit_Check_USD']).abs().max())

def money(x, digits=0):
    return f"${x:,.{digits}f}"

def num(x, digits=1):
    return f"{x:,.{digits}f}"

def pct(x, digits=1):
    return f"{x*100:,.{digits}f}%"

def mult(x, digits=2):
    return f"{x:,.{digits}f}x"

def safe_id(s):
    return ''.join(c if c.isalnum() else '-' for c in s.lower()).strip('-')

def group_summary(group_col):
    return (work.groupby(group_col)
        .agg(
            tx=('Transaction_ID','count'),
            avg_retail=('Retail_Price_USD','mean'),
            avg_resale=('Resale_Price_USD','mean'),
            avg_profit=('Profit_Margin_USD','mean'),
            median_profit=('Profit_Margin_USD','median'),
            avg_ratio=('Resale_Retail_Ratio','mean'),
            premium_rate=('Sold_Above_Retail','mean'),
            avg_days=('Days_in_Inventory','mean')
        )
        .reset_index())

model = group_summary('Shoe_Model').sort_values('avg_profit', ascending=False)
color = group_summary('Colorway').sort_values('avg_profit', ascending=False)
condition = group_summary('Condition').sort_values('avg_profit', ascending=False)
channel = group_summary('Sales_Channel').sort_values('avg_profit', ascending=False)
yearly = (work.groupby('Year')
    .agg(tx=('Transaction_ID','count'), avg_resale=('Resale_Price_USD','mean'), avg_profit=('Profit_Margin_USD','mean'), avg_ratio=('Resale_Retail_Ratio','mean'), premium_rate=('Sold_Above_Retail','mean'), avg_days=('Days_in_Inventory','mean'))
    .reset_index())
calendar_order = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
monthly_season = (work.groupby(['Month','Calendar_Month'])
    .agg(tx=('Transaction_ID','count'), avg_resale=('Resale_Price_USD','mean'), avg_profit=('Profit_Margin_USD','mean'), premium_rate=('Sold_Above_Retail','mean'), avg_days=('Days_in_Inventory','mean'))
    .reset_index()
    .sort_values('Month'))
monthly_ts = (work.groupby('YearMonth')
    .agg(tx=('Transaction_ID','count'), avg_resale=('Resale_Price_USD','mean'), avg_profit=('Profit_Margin_USD','mean'), avg_days=('Days_in_Inventory','mean'), premium_rate=('Sold_Above_Retail','mean'))
    .reset_index())
combo = (work.groupby(['Shoe_Model','Colorway'])
    .agg(tx=('Transaction_ID','count'), avg_resale=('Resale_Price_USD','mean'), avg_profit=('Profit_Margin_USD','mean'), avg_days=('Days_in_Inventory','mean'), premium_rate=('Sold_Above_Retail','mean'))
    .reset_index())
combo_top = combo[combo['tx'] >= 30].sort_values('avg_profit', ascending=False).head(10)
combo_bottom = combo[combo['tx'] >= 30].sort_values('avg_profit', ascending=True).head(8)

# KPI values
kpis = {
    'tx': len(work),
    'date_min': work['Sale_Date'].min().date().isoformat(),
    'date_max': work['Sale_Date'].max().date().isoformat(),
    'avg_profit': work['Profit_Margin_USD'].mean(),
    'premium_rate': work['Sold_Above_Retail'].mean(),
    'avg_days': work['Days_in_Inventory'].mean(),
    'avg_ratio': work['Resale_Retail_Ratio'].mean(),
    'avg_retail': work['Retail_Price_USD'].mean(),
    'avg_resale': work['Resale_Price_USD'].mean(),
    'median_profit': work['Profit_Margin_USD'].median(),
    'p10_profit': work['Profit_Margin_USD'].quantile(.10),
    'p90_profit': work['Profit_Margin_USD'].quantile(.90),
}
top_color = color.iloc[0]
top_channel_margin = channel.sort_values('avg_profit', ascending=False).iloc[0]
fastest_channel = channel.sort_values('avg_days', ascending=True).iloc[0]
best_balanced_channel = channel.assign(profit_per_day=lambda x: x['avg_profit']/x['avg_days']).sort_values('profit_per_day', ascending=False).iloc[0]

def color_scale(i):
    palette = ['#2563eb','#7c3aed','#0891b2','#059669','#d97706','#dc2626','#4f46e5','#0f766e','#9333ea','#ea580c','#64748b','#be123c']
    return palette[i % len(palette)]

def axis_fmt(v, kind):
    if kind == 'money': return money(v,0)
    if kind == 'pct': return pct(v,0)
    if kind == 'ratio': return mult(v,1)
    return num(v,0)

def bar_chart(items, width=760, height=340, value_key='value', label_key='label', title='', subtitle='', kind='money', horizontal=True, colors=None, max_bars=None, show_values=True, zero_line=True):
    data = list(items)
    if max_bars:
        data = data[:max_bars]
    if not data:
        return ''
    margin = dict(top=38, right=34, bottom=44, left=170 if horizontal else 52)
    plot_w = width - margin['left'] - margin['right']
    plot_h = height - margin['top'] - margin['bottom']
    vals = [float(d[value_key]) for d in data]
    vmin = min(vals + ([0] if zero_line else []))
    vmax = max(vals + ([0] if zero_line else []))
    if math.isclose(vmin, vmax):
        vmin -= 1; vmax += 1
    pad = (vmax - vmin) * 0.12
    vmin -= pad; vmax += pad
    def xscale(v): return margin['left'] + (v - vmin) / (vmax - vmin) * plot_w
    def yscale(i): return margin['top'] + i * (plot_h / len(data))
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{escape(title)}" class="chart">']
    svg.append(f'<text x="0" y="18" class="chart-title">{escape(title)}</text>')
    if subtitle:
        svg.append(f'<text x="0" y="34" class="chart-subtitle">{escape(subtitle)}</text>')
    # grid/ticks
    for t in np.linspace(vmin, vmax, 5):
        x = xscale(t)
        svg.append(f'<line x1="{x:.1f}" y1="{margin["top"]}" x2="{x:.1f}" y2="{margin["top"]+plot_h}" class="grid"/>')
        svg.append(f'<text x="{x:.1f}" y="{height-12}" text-anchor="middle" class="axis">{escape(axis_fmt(t, kind))}</text>')
    if zero_line and vmin < 0 < vmax:
        x0 = xscale(0)
        svg.append(f'<line x1="{x0:.1f}" y1="{margin["top"]}" x2="{x0:.1f}" y2="{margin["top"]+plot_h}" class="zero"/>')
    band = plot_h / len(data)
    bar_h = min(26, band * .64)
    for i, d in enumerate(data):
        label = str(d[label_key])
        val = float(d[value_key])
        y = yscale(i) + (band - bar_h)/2
        x0 = xscale(0) if zero_line and vmin < 0 < vmax else margin['left']
        x1 = xscale(val)
        x = min(x0, x1)
        bw = abs(x1 - x0)
        col = colors[i] if colors else color_scale(i)
        svg.append(f'<text x="{margin["left"]-10}" y="{y+bar_h/2+4:.1f}" text-anchor="end" class="label">{escape(label)}</text>')
        svg.append(f'<rect x="{x:.1f}" y="{y:.1f}" width="{bw:.1f}" height="{bar_h:.1f}" rx="5" fill="{col}" opacity="0.88"/>')
        if show_values:
            anchor = 'start' if val >= 0 else 'end'
            tx = x1 + (6 if val >= 0 else -6)
            svg.append(f'<text x="{tx:.1f}" y="{y+bar_h/2+4:.1f}" text-anchor="{anchor}" class="value">{escape(axis_fmt(val, kind))}</text>')
    svg.append('</svg>')
    return '\n'.join(svg)

def line_chart(rows, x_key, y_keys, labels, width=900, height=360, title='', subtitle='', kind='money'):
    data = rows.to_dict('records') if hasattr(rows, 'to_dict') else list(rows)
    margin = dict(top=42, right=28, bottom=70, left=64)
    plot_w = width - margin['left'] - margin['right']
    plot_h = height - margin['top'] - margin['bottom']
    vals = [float(r[k]) for r in data for k in y_keys]
    ymin, ymax = min(vals), max(vals)
    pad = (ymax - ymin) * .14 if ymax != ymin else 1
    ymin -= pad; ymax += pad
    def xscale(i): return margin['left'] + i/(max(len(data)-1,1))*plot_w
    def yscale(v): return margin['top'] + (ymax-v)/(ymax-ymin)*plot_h
    svg=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{escape(title)}" class="chart wide-chart">']
    svg.append(f'<text x="0" y="18" class="chart-title">{escape(title)}</text>')
    if subtitle: svg.append(f'<text x="0" y="34" class="chart-subtitle">{escape(subtitle)}</text>')
    for t in np.linspace(ymin, ymax, 5):
        y=yscale(t)
        svg.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{margin["left"]+plot_w}" y2="{y:.1f}" class="grid"/>')
        svg.append(f'<text x="{margin["left"]-8}" y="{y+4:.1f}" text-anchor="end" class="axis">{escape(axis_fmt(t, kind))}</text>')
    # x labels sparse
    step = max(1, math.ceil(len(data)/10))
    for i,r in enumerate(data):
        if i % step == 0 or i == len(data)-1:
            x=xscale(i)
            svg.append(f'<text transform="translate({x:.1f},{height-42}) rotate(-35)" text-anchor="end" class="axis">{escape(str(r[x_key]))}</text>')
    for ki,k in enumerate(y_keys):
        col=color_scale(ki)
        pts=[]
        for i,r in enumerate(data):
            pts.append(f'{xscale(i):.1f},{yscale(float(r[k])):.1f}')
        svg.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="{col}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>')
        for i,r in enumerate(data):
            if i in (0, len(data)-1) or (i % max(1, len(data)//8) == 0):
                svg.append(f'<circle cx="{xscale(i):.1f}" cy="{yscale(float(r[k])):.1f}" r="3.5" fill="{col}"/>')
        lx = margin['left'] + ki*190
        svg.append(f'<rect x="{lx}" y="{height-24}" width="12" height="12" rx="2" fill="{col}"/><text x="{lx+18}" y="{height-14}" class="legend">{escape(labels[k])}</text>')
    svg.append('</svg>')
    return '\n'.join(svg)

def scatter_chart(rows, width=760, height=390, title='', subtitle=''):
    data = rows.to_dict('records')
    margin = dict(top=42, right=42, bottom=60, left=74)
    plot_w = width - margin['left'] - margin['right']
    plot_h = height - margin['top'] - margin['bottom']
    xs=[float(r['avg_days']) for r in data]
    ys=[float(r['avg_profit']) for r in data]
    sizes=[float(r['tx']) for r in data]
    xmin,xmax=min(xs),max(xs); ymin,ymax=min(ys),max(ys)
    xpad=(xmax-xmin)*.16 or 1; ypad=(ymax-ymin)*.22 or 1
    xmin-=xpad; xmax+=xpad; ymin-=ypad; ymax+=ypad
    def xscale(v): return margin['left'] + (v-xmin)/(xmax-xmin)*plot_w
    def yscale(v): return margin['top'] + (ymax-v)/(ymax-ymin)*plot_h
    svg=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{escape(title)}" class="chart">']
    svg.append(f'<text x="0" y="18" class="chart-title">{escape(title)}</text>')
    if subtitle: svg.append(f'<text x="0" y="34" class="chart-subtitle">{escape(subtitle)}</text>')
    for t in np.linspace(xmin, xmax, 5):
        x=xscale(t); svg.append(f'<line x1="{x:.1f}" y1="{margin["top"]}" x2="{x:.1f}" y2="{margin["top"]+plot_h}" class="grid"/>')
        svg.append(f'<text x="{x:.1f}" y="{height-22}" text-anchor="middle" class="axis">{num(t,0)}d</text>')
    for t in np.linspace(ymin, ymax, 5):
        y=yscale(t); svg.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{margin["left"]+plot_w}" y2="{margin["left"]+plot_w}" class="grid" opacity="0"/>')
        svg.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{margin["left"]+plot_w}" y2="{y:.1f}" class="grid"/>')
        svg.append(f'<text x="{margin["left"]-8}" y="{y+4:.1f}" text-anchor="end" class="axis">{money(t,0)}</text>')
    svg.append(f'<text x="{margin["left"]+plot_w/2}" y="{height-4}" text-anchor="middle" class="axis-label">Average Days in Inventory</text>')
    svg.append(f'<text transform="translate(16,{margin["top"]+plot_h/2}) rotate(-90)" text-anchor="middle" class="axis-label">Average Profit Margin</text>')
    for i,r in enumerate(data):
        radius=8 + (float(r['tx'])-min(sizes))/(max(sizes)-min(sizes) or 1)*8
        x=xscale(float(r['avg_days'])); y=yscale(float(r['avg_profit']))
        col=color_scale(i)
        svg.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{radius:.1f}" fill="{col}" opacity="0.78"/>')
        svg.append(f'<text x="{x+radius+5:.1f}" y="{y+4:.1f}" class="label small">{escape(str(r["Sales_Channel"]))}</text>')
    svg.append('</svg>')
    return '\n'.join(svg)

def table_html(df_in, cols, formatters=None, limit=None, class_name='data-table'):
    rows = df_in.head(limit) if limit else df_in
    formatters = formatters or {}
    html=[f'<table class="{class_name}"><thead><tr>']
    for key,label in cols:
        html.append(f'<th>{escape(label)}</th>')
    html.append('</tr></thead><tbody>')
    for _,r in rows.iterrows():
        html.append('<tr>')
        for key,label in cols:
            val = r[key]
            if key in formatters:
                val = formatters[key](val)
            elif isinstance(val, (float, np.floating)):
                val = num(val,1)
            else:
                val = str(val)
            klass = ' class="num"' if key not in ('Shoe_Model','Colorway','Condition','Sales_Channel','Year','YearMonth','Calendar_Month') else ''
            html.append(f'<td{klass}>{escape(str(val))}</td>')
        html.append('</tr>')
    html.append('</tbody></table>')
    return ''.join(html)

fmt_common = {
