channel_sorted_velocity = channel.sort_values('avg_days')
channel_bars_profit = [{'label': r['Sales_Channel'], 'value': r['avg_profit']} for _,r in channel.sort_values('avg_profit', ascending=True).iterrows()]
channel_bars_days = [{'label': r['Sales_Channel'], 'value': r['avg_days']} for _,r in channel.sort_values('avg_days', ascending=False).iterrows()]
