    sizes=[float(r['tx']) for r in data]
    xmin,xmax=min(xs),max(xs); ymin,ymax=min(ys),max(ys)
    xpad=(xmax-xmin)*.16 or 1; ypad=(ymax-ymin)*.22 or 1
    xmin-=xpad; xmax+=xpad; ymin-=ypad; ymax+=ypad
    def xscale(v): return margin['left'] + (v-xmin)/(xmax-xmin)*plot_w
    def yscale(v): return margin['top'] + (ymax-v)/(ymax-ymin)*plot_h
    svg=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{escape(title)}" class="chart">']
    svg.append(f'<text x="0" y="18" class="chart-title">{escape(title)}</text>')
    if subtitle: svg.append(f'<text x="0" y="34" class="chart-subtitle">{escape(subtitle)}</text>')
    for t in np.linspace(xmin, xmax, 5):
        x=xscale(t); svg.append(f'<line x1="{x:.1f}" y1="{margin["top"]}" x2="{x:.1f}" y2="{margin["top"]+plot_h}" class="grid"/>')
        svg.append(f'<text x="{x:.1f}" y="{height-22}" text-anchor="middle" class="axis">{num(t,0)}d</text>')
    for t in np.linspace(ymin, ymax, 5):
        y=yscale(t); svg.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{margin["left"]+plot_w}" y2="{margin["left"]+plot_w}" class="grid" opacity="0"/>')
        svg.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{margin["left"]+plot_w}" y2="{y:.1f}" class="grid"/>')
        svg.append(f'<text x="{margin["left"]-8}" y="{y+4:.1f}" text-anchor="end" class="axis">{money(t,0)}</text>')
    svg.append(f'<text x="{margin["left"]+plot_w/2}" y="{height-4}" text-anchor="middle" class="axis-label">Average Days in Inventory</text>')
    svg.append(f'<text transform="translate(16,{margin["top"]+plot_h/2}) rotate(-90)" text-anchor="middle" class="axis-label">Average Profit Margin</text>')
    for i,r in enumerate(data):
        radius=8 + (float(r['tx'])-min(sizes))/(max(sizes)-min(sizes) or 1)*8
        x=xscale(float(r['avg_days'])); y=yscale(float(r['avg_profit']))
        col=color_scale(i)
        svg.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{radius:.1f}" fill="{col}" opacity="0.78"/>')
        svg.append(f'<text x="{x+radius+5:.1f}" y="{y+4:.1f}" class="label small">{escape(str(r["Sales_Channel"]))}</text>')
    svg.append('</svg>')
    return '\n'.join(svg)

def table_html(df_in, cols, formatters=None, limit=None, class_name='data-table'):
    rows = df_in.head(limit) if limit else df_in
    formatters = formatters or {}
    html=[f'<table class="{class_name}"><thead><tr>']
    for key,label in cols:
        html.append(f'<th>{escape(label)}</th>')
    html.append('</tr></thead><tbody>')
    for _,r in rows.iterrows():
        html.append('<tr>')
        for key,label in cols:
            val = r[key]
            if key in formatters:
                val = formatters[key](val)
            elif isinstance(val, (float, np.floating)):
                val = num(val,1)
            else:
                val = str(val)
            klass = ' class="num"' if key not in ('Shoe_Model','Colorway','Condition','Sales_Channel','Year','YearMonth','Calendar_Month') else ''
            html.append(f'<td{klass}>{escape(str(val))}</td>')
        html.append('</tr>')
    html.append('</tbody></table>')
    return ''.join(html)

